CREATE DATABASE IF NOT EXISTS cafe_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE cafe_management;

CREATE TABLE roles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(50) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL);
CREATE TABLE outlets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, address TEXT, timezone VARCHAR(50) NOT NULL DEFAULT 'Asia/Jakarta', status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, password_hash VARCHAR(255), google_sub VARCHAR(255) UNIQUE, status ENUM('ACTIVE','INACTIVE','LOCKED') NOT NULL DEFAULT 'ACTIVE', last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE user_roles (user_id BIGINT UNSIGNED NOT NULL, role_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE user_outlets (user_id BIGINT UNSIGNED NOT NULL, outlet_id BIGINT UNSIGNED NOT NULL, is_default TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY(user_id,outlet_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(outlet_id) REFERENCES outlets(id));
CREATE TABLE units (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(50) NOT NULL, base_conversion DECIMAL(18,6) NOT NULL DEFAULT 1);
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE');
CREATE TABLE products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(60) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, category_id BIGINT UNSIGNED, product_type ENUM('FOOD','BEVERAGE','MERCHANDISE','SERVICE') NOT NULL DEFAULT 'BEVERAGE', base_unit_id BIGINT UNSIGNED, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE', FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(base_unit_id) REFERENCES units(id));
CREATE TABLE stock_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(60) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, unit_id BIGINT UNSIGNED NOT NULL, item_type ENUM('RAW_MATERIAL','PACKAGING','OTHER') DEFAULT 'RAW_MATERIAL', reorder_level DECIMAL(18,6) DEFAULT 0, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE', FOREIGN KEY(unit_id) REFERENCES units(id));
CREATE TABLE recipes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, version_no INT NOT NULL DEFAULT 1, yield_qty DECIMAL(18,6) NOT NULL DEFAULT 1, is_active TINYINT(1) DEFAULT 1, UNIQUE(outlet_id,product_id,version_no), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE recipe_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, recipe_id BIGINT UNSIGNED NOT NULL, stock_item_id BIGINT UNSIGNED NOT NULL, qty DECIMAL(18,6) NOT NULL, unit_id BIGINT UNSIGNED NOT NULL, FOREIGN KEY(recipe_id) REFERENCES recipes(id), FOREIGN KEY(stock_item_id) REFERENCES stock_items(id), FOREIGN KEY(unit_id) REFERENCES units(id));
CREATE TABLE outlet_products (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, selling_price DECIMAL(18,2) NOT NULL, tax_rate DECIMAL(7,4) NOT NULL DEFAULT 0, is_available TINYINT(1) DEFAULT 1, recipe_id BIGINT UNSIGNED NULL, UNIQUE(outlet_id,product_id), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(product_id) REFERENCES products(id), FOREIGN KEY(recipe_id) REFERENCES recipes(id));
CREATE TABLE dining_tables (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, code VARCHAR(30) NOT NULL, name VARCHAR(80) NOT NULL, capacity INT DEFAULT 2, status ENUM('AVAILABLE','OCCUPIED','RESERVED','INACTIVE') DEFAULT 'AVAILABLE', qr_token VARCHAR(100) UNIQUE, UNIQUE(outlet_id,code), FOREIGN KEY(outlet_id) REFERENCES outlets(id));
CREATE TABLE inventory_stocks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, stock_item_id BIGINT UNSIGNED NOT NULL, qty_on_hand DECIMAL(18,6) NOT NULL DEFAULT 0, avg_cost DECIMAL(18,6) NOT NULL DEFAULT 0, UNIQUE(outlet_id,stock_item_id), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(stock_item_id) REFERENCES stock_items(id));
CREATE TABLE inventory_movements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, stock_item_id BIGINT UNSIGNED NOT NULL, movement_type ENUM('PURCHASE_IN','SALE_OUT','ADJUSTMENT_IN','ADJUSTMENT_OUT','RETURN_IN','WASTE_OUT','TRANSFER_IN','TRANSFER_OUT') NOT NULL, qty DECIMAL(18,6) NOT NULL, unit_cost DECIMAL(18,6) NOT NULL DEFAULT 0, reference_type VARCHAR(50), reference_id BIGINT UNSIGNED NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_inv_move(outlet_id,stock_item_id,created_at), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(stock_item_id) REFERENCES stock_items(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(50) NOT NULL UNIQUE, outlet_id BIGINT UNSIGNED NOT NULL, customer_id BIGINT UNSIGNED NULL, table_id BIGINT UNSIGNED NULL, order_channel ENUM('POS','DINE_IN_QR','DINE_IN_STAFF','TAKEAWAY','DELIVERY') NOT NULL DEFAULT 'POS', status ENUM('OPEN','CONFIRMED','PREPARING','READY','SERVED','PAID','CANCELLED','REFUNDED') NOT NULL DEFAULT 'OPEN', subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, discount_total DECIMAL(18,2) NOT NULL DEFAULT 0, tax_total DECIMAL(18,2) NOT NULL DEFAULT 0, grand_total DECIMAL(18,2) NOT NULL DEFAULT 0, ordered_at DATETIME NOT NULL, closed_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_orders_outlet_date(outlet_id,ordered_at,status), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(customer_id) REFERENCES users(id), FOREIGN KEY(table_id) REFERENCES dining_tables(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, product_id BIGINT UNSIGNED NOT NULL, qty DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,2) NOT NULL, discount DECIMAL(18,2) NOT NULL DEFAULT 0, line_total DECIMAL(18,2) NOT NULL, hpp_total DECIMAL(18,2) NOT NULL DEFAULT 0, notes VARCHAR(255), FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, method ENUM('CASH','BANK_TRANSFER','QRIS','CARD','OTHER') NOT NULL, amount DECIMAL(18,2) NOT NULL, reference_no VARCHAR(100), status ENUM('PENDING','SUCCESS','FAILED','REFUNDED') DEFAULT 'PENDING', paid_at DATETIME NULL, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(30) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, account_type ENUM('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE') NOT NULL, parent_id BIGINT UNSIGNED NULL, is_cash_bank TINYINT(1) DEFAULT 0, status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE', FOREIGN KEY(parent_id) REFERENCES accounts(id));
CREATE TABLE journal_entries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, journal_no VARCHAR(50) UNIQUE NOT NULL, entry_date DATE NOT NULL, outlet_id BIGINT UNSIGNED NULL, source_type VARCHAR(50), source_id BIGINT UNSIGNED NULL, memo VARCHAR(255), status ENUM('POSTED','REVERSED') DEFAULT 'POSTED', created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_journal_date(outlet_id,entry_date,status), FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE journal_lines (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, journal_entry_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, debit DECIMAL(18,2) NOT NULL DEFAULT 0, credit DECIMAL(18,2) NOT NULL DEFAULT 0, memo VARCHAR(255), FOREIGN KEY(journal_entry_id) REFERENCES journal_entries(id), FOREIGN KEY(account_id) REFERENCES accounts(id));
CREATE TABLE cash_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, outlet_id BIGINT UNSIGNED NOT NULL, account_id BIGINT UNSIGNED NOT NULL, txn_type ENUM('IN','OUT') NOT NULL, amount DECIMAL(18,2) NOT NULL, txn_date DATETIME NOT NULL, reference_type VARCHAR(50), reference_id BIGINT UNSIGNED NULL, description VARCHAR(255), created_by BIGINT UNSIGNED NULL, FOREIGN KEY(outlet_id) REFERENCES outlets(id), FOREIGN KEY(account_id) REFERENCES accounts(id), FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, outlet_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, before_json JSON NULL, after_json JSON NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_audit(entity_type,entity_id,created_at), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(outlet_id) REFERENCES outlets(id));

